-- ESPEJO EXACTO DE BITRIX — corte 2026-08-17 14:53 — parte 1 de 3 (9000 deals)
-- SIN GUARDA: pisa la etapa de TODOS los leads del archivo, sin excepciones.
-- La base queda identica a Bitrix al momento del export. Correr en orden.

DROP TABLE IF EXISTS bkp_espejo_20260817;
CREATE TABLE bkp_espejo_20260817 AS
SELECT * FROM public.bitrix_webhook_leads WHERE empresa='novonet';

BEGIN;

ON CONFLICT (empresa, bitrix_id) DO UPDATE SET etapa = EXCLUDED.etapa, etapa_bitrix = EXCLUDED.etapa_bitrix, responsible = COALESCE(EXCLUDED.responsible, l.responsible), created_at = EXCLUDED.created_at, updated_at = NOW();

COMMIT;
